/**
 * External dependencies
 */
import { isEqual, keyBy, omit } from 'lodash';
import type { AnyAction } from '@nab/types';

/**
 * Internal dependencies
 */
import { INIT_STATE } from './config';
import type { Action } from './actions';
import type { State } from './types';

export function reducer( state = INIT_STATE, action: AnyAction ): State {
	return actualReducer( state, action as Action ) ?? state;
}

function actualReducer( state: State, action: Action ): State {
	switch ( action.type ) {
		case 'ADD_EXPERIMENT_TYPE_DEFINITIONS': {
			const newDefinitions = {
				...state.experimentTypeDefinitions,
				...keyBy( action.definitions, 'name' ),
			};
			if ( isEqual( state.experimentTypeDefinitions, newDefinitions ) ) {
				return state;
			}

			return initializeExperimentTypes( {
				...state,
				experimentTypeDefinitions: newDefinitions,
			} );
		}

		case 'REMOVE_EXPERIMENT_TYPE_DEFINITIONS': {
			const newDefinitions = omit(
				state.experimentTypeDefinitions,
				action.names
			);
			if ( isEqual( state.experimentTypeDefinitions, newDefinitions ) ) {
				return state;
			}

			return initializeExperimentTypes( {
				...state,
				experimentTypeDefinitions: newDefinitions,
			} );
		}

		case 'ADD_EXPERIMENT_TYPE_RUNTIMES': {
			const newRuntimes = action.runtimes.reduce(
				( runtimes, registration ) => ( {
					...runtimes,
					[ registration.name ]: registration.runtime,
				} ),
				state.experimentTypeRuntimes
			);
			if ( isEqual( state.experimentTypeRuntimes, newRuntimes ) ) {
				return state;
			}

			return initializeExperimentTypes( {
				...state,
				experimentTypeRuntimes: newRuntimes,
			} );
		}

		case 'REMOVE_EXPERIMENT_TYPE_RUNTIMES': {
			const newRuntimes = omit(
				state.experimentTypeRuntimes,
				action.names
			);
			if ( isEqual( state.experimentTypeRuntimes, newRuntimes ) ) {
				return state;
			}

			return initializeExperimentTypes( {
				...state,
				experimentTypeRuntimes: newRuntimes,
			} );
		}
	}
}

function initializeExperimentTypes( state: State ): State {
	const experimentTypes = Object.keys(
		state.experimentTypeDefinitions
	).reduce< State[ 'experimentTypes' ] >( ( types, name ) => {
		const runtime = state.experimentTypeRuntimes[ name ];
		if ( ! runtime ) {
			return types;
		}

		return {
			...types,
			[ name ]: {
				...state.experimentTypeDefinitions[ name ],
				...runtime,
			} as State[ 'experimentTypes' ][ string ],
		};
	}, {} );

	if ( isEqual( state.experimentTypes, experimentTypes ) ) {
		return state;
	}

	return {
		...state,
		experimentTypes,
	};
}
