/**
 * WordPress dependencies
 */
import { select, dispatch } from '@safe-wordpress/data';

/**
 * External dependencies
 */
import { isFunction, isObject } from 'lodash';
import { isValidIcon } from '@nab/utils';
import type {
	Dict,
	ExperimentTypeDefinition,
	ExperimentTypeName,
	ExperimentTypeRuntime,
	Maybe,
} from '@nab/types';

/**
 * Internal dependencies
 */
import { store as NAB_EXPERIMENTS } from '../store';

const defaultExpected = {
	pageViews: {
		average: 5000,
		median: 5000,
		p25: 3000,
		p75: 7000,
	},
};

export function registerExperimentTypeDefinition(
	name: ExperimentTypeName,
	definition: Dict
): Maybe< ExperimentTypeDefinition > {
	const registeredDefinition = {
		description: '',
		expected: defaultExpected,
		...definition,
		name,
	};

	if ( 'nab/heatmap' !== name ) {
		if ( ! isValidName( name ) ) {
			return;
		}

		if ( select( NAB_EXPERIMENTS ).getExperimentType( name ) ) {
			// eslint-disable-next-line no-console
			console.error(
				`Experiment type “${ name }” is already registered.`
			);
			return;
		}

		if ( ! hasHelp( registeredDefinition ) ) {
			// eslint-disable-next-line no-console
			console.error(
				`The experiment “${ name }” must provide help strings explaining the control version and its variants.`
			);
			return;
		}

		if ( ! hasCategory( registeredDefinition ) ) {
			// eslint-disable-next-line no-console
			console.error(
				`The experiment “${ name }” must have a valid category.`
			);
			return;
		}

		if ( ! hasTitle( registeredDefinition ) ) {
			// eslint-disable-next-line no-console
			console.error( `The experiment “${ name }” must have a title.` );
			return;
		}

		if ( ! hasDefaultValues( registeredDefinition ) ) {
			// eslint-disable-next-line no-console
			console.error(
				`The experiment “${ name }” must specify original and alternative default values.`
			);
			return;
		}
	}

	void dispatch( NAB_EXPERIMENTS ).addExperimentTypeDefinitions(
		registeredDefinition as ExperimentTypeDefinition
	);

	return registeredDefinition as ExperimentTypeDefinition;
}

export function registerExperimentTypeRuntime(
	name: ExperimentTypeName,
	runtime: Dict
): Maybe< ExperimentTypeRuntime > {
	const registeredRuntime = {
		supports: {},
		checks: {
			getControlError: (): string | false => false,
			getAlternativeError: (): string | false => false,
		},
		...runtime,
	};

	if ( ! isValidName( name ) ) {
		return;
	}

	if ( select( NAB_EXPERIMENTS ).getExperimentType( name ) ) {
		// eslint-disable-next-line no-console
		console.error( `Experiment type “${ name }” is already registered.` );
		return;
	}

	if ( ! select( NAB_EXPERIMENTS ).hasExperimentTypeDefinition( name ) ) {
		return;
	}

	if ( 'nab/heatmap' !== name && ! hasChecks( registeredRuntime ) ) {
		// eslint-disable-next-line no-console
		console.error(
			`Experiment type “${ name }” must provide at least two checks: “getControlError” and “getAlternativeError”.`
		);
		return;
	}

	if ( ! hasIcon( registeredRuntime ) ) {
		// eslint-disable-next-line no-console
		console.error( `The experiment “${ name }” must have an icon.` );
		return;
	}

	if ( ! isValidIcon( registeredRuntime.icon ) ) {
		// eslint-disable-next-line no-console
		console.error(
			'The icon passed is invalid. The icon should be an element or a function.'
		);
		return;
	}

	if ( 'nab/heatmap' !== name && ! hasViews( registeredRuntime ) ) {
		// eslint-disable-next-line no-console
		console.error(
			`The experiment “${ name }” must specify original and alternative edit views.`
		);
		return;
	}

	void dispatch( NAB_EXPERIMENTS ).addExperimentTypeRuntimes( {
		name,
		runtime: registeredRuntime as unknown as ExperimentTypeRuntime,
	} );

	return registeredRuntime as unknown as ExperimentTypeRuntime;
}

function isValidName( name: ExperimentTypeName ): boolean {
	if ( typeof name !== 'string' ) {
		// eslint-disable-next-line no-console
		console.error( 'Test type names must be strings.' );
		return false;
	}

	if ( ! /^[a-z][a-z0-9-]*\/[a-z][a-z0-9-]*$/.test( name ) ) {
		// eslint-disable-next-line no-console
		console.error(
			'Test type names must contain a namespace prefix, include only lowercase alphanumeric characters or dashes, and start with a letter. Example: my-plugin/my-custom-experiment'
		);
		return false;
	}

	return true;
}

const hasHelp = (
	x: Partial< ExperimentTypeDefinition >
): x is Pick< ExperimentTypeDefinition, 'help' > =>
	!! x.help &&
	'string' === typeof x.help.original &&
	!! x.help.original &&
	'string' === typeof x.help.alternative &&
	!! x.help.alternative;

const hasCategory = (
	x: Partial< ExperimentTypeDefinition >
): x is Pick< ExperimentTypeDefinition, 'category' > =>
	[ 'page', 'global', 'woocommerce', 'other' ].includes( x.category ?? '' );

const hasTitle = (
	x: Partial< ExperimentTypeDefinition >
): x is Pick< ExperimentTypeDefinition, 'title' > =>
	'string' === typeof x.title && !! x.title;

const hasIcon = (
	x: Partial< ExperimentTypeRuntime >
): x is Pick< ExperimentTypeRuntime, 'icon' > => 'icon' in x;

const hasViews = (
	x: Partial< ExperimentTypeRuntime >
): x is Pick< ExperimentTypeRuntime, 'views' > =>
	isFunction( x.views?.original ) && isFunction( x.views?.alternative );

const hasChecks = (
	x: Partial< ExperimentTypeRuntime >
): x is Pick< ExperimentTypeRuntime, 'checks' > =>
	isFunction( x.checks?.getControlError ) &&
	isFunction( x.checks?.getAlternativeError );

const hasDefaultValues = (
	x: Partial< ExperimentTypeDefinition >
): x is Pick< ExperimentTypeDefinition, 'defaults' > =>
	isObject( x.defaults?.original ) && isObject( x.defaults?.alternative );
