/**
 * External dependencies
 */
import { castArray } from 'lodash';
import type {
	ExperimentTypeDefinition,
	ExperimentTypeName,
	ExperimentTypeRuntime,
} from '@nab/types';

export type Action =
	| AddExperimentTypeDefinitions
	| RemoveExperimentTypeDefinitions
	| AddExperimentTypeRuntimes
	| RemoveExperimentTypeRuntimes;

export function addExperimentTypeDefinitions(
	definitions:
		ExperimentTypeDefinition | ReadonlyArray< ExperimentTypeDefinition >
): AddExperimentTypeDefinitions {
	return {
		type: 'ADD_EXPERIMENT_TYPE_DEFINITIONS',
		definitions: castArray( definitions ),
	};
}

export function removeExperimentTypeDefinitions(
	names: ExperimentTypeName | ReadonlyArray< ExperimentTypeName >
): RemoveExperimentTypeDefinitions {
	return {
		type: 'REMOVE_EXPERIMENT_TYPE_DEFINITIONS',
		names: castArray( names ),
	};
}

export function addExperimentTypeRuntimes(
	runtimes:
		| ExperimentTypeRuntimeRegistration
		| ReadonlyArray< ExperimentTypeRuntimeRegistration >
): AddExperimentTypeRuntimes {
	return {
		type: 'ADD_EXPERIMENT_TYPE_RUNTIMES',
		runtimes: castArray( runtimes ),
	};
}

export function removeExperimentTypeRuntimes(
	names: ExperimentTypeName | ReadonlyArray< ExperimentTypeName >
): RemoveExperimentTypeRuntimes {
	return {
		type: 'REMOVE_EXPERIMENT_TYPE_RUNTIMES',
		names: castArray( names ),
	};
}

// ============
// HELPER TYPES
// ============

type AddExperimentTypeDefinitions = {
	readonly type: 'ADD_EXPERIMENT_TYPE_DEFINITIONS';
	readonly definitions: ReadonlyArray< ExperimentTypeDefinition >;
};

type RemoveExperimentTypeDefinitions = {
	readonly type: 'REMOVE_EXPERIMENT_TYPE_DEFINITIONS';
	readonly names: ReadonlyArray< ExperimentTypeName >;
};

type AddExperimentTypeRuntimes = {
	readonly type: 'ADD_EXPERIMENT_TYPE_RUNTIMES';
	readonly runtimes: ReadonlyArray< ExperimentTypeRuntimeRegistration >;
};

type RemoveExperimentTypeRuntimes = {
	readonly type: 'REMOVE_EXPERIMENT_TYPE_RUNTIMES';
	readonly names: ReadonlyArray< ExperimentTypeName >;
};

export type ExperimentTypeRuntimeRegistration = {
	readonly name: ExperimentTypeName;
	readonly runtime: ExperimentTypeRuntime;
};
